/** A page's route path from its source-relative path (cleanUrls drops `index`/the extension). */
function pagePath(relativePath: string): string {
  return `/${relativePath}`.replace(/index\.md$/, "").replace(/\.md$/, "");
}

/** The locale a page belongs to, from its docs-relative path (`hu/guide/cli.md` → `hu`). */
function localeOfPage(relativePath: string): DocsLocale {
  return NON_ROOT_LOCALES.find((key) => relativePath.startsWith(`${key}/`)) ?? "root";
