function apiSidebarFor(relativePath: string): DefaultTheme.SidebarItem[] | undefined {
  const routes = apiSidebarRoutesByLocale[localeOfPage(relativePath)];
  if (!routes) return undefined;
  const path = pagePath(relativePath);
  let bestKey: string | undefined;
  for (const key of Object.keys(routes)) {
    if (path.startsWith(key) && (!bestKey || key.length > bestKey.length)) bestKey = key;
  }
  return bestKey ? routes[bestKey] : undefined;
}"}

